import sys, re
from xml.dom import minidom

path = "quarterly_unpacked/word/document.xml"
with open(path, "r", encoding="utf-8") as f:
    xml = f.read()

doc = minidom.parseString(xml)
ns = "http://schemas.openxmlformats.org/wordprocessingml/2006/main"

def wtag(elem, local):
    return elem.getElementsByTagNameNS(ns, local)

def local_name(tag):
    return tag.split("}")[-1]

paras = doc.getElementsByTagNameNS(ns, "p")
print("Total paragraphs:", len(paras))
for i, p in enumerate(paras):
    pPrs = wtag(p, "pPr")
    style = None
    if pPrs:
        for s in wtag(pPrs[0], "pStyle"):
            style = s.getAttributeNS(ns, "val")
    texts = []
    for t in wtag(p, "t"):
        texts.append(t.firstChild.nodeValue if t.firstChild else "")
    txt = "".join(texts)
    if style:
        print(f"p[{i}] style={style!r} text={txt!r}")

