import os, sys, glob

# Locate skill root (directory containing scripts/document.py)
def find_skill_root():
    here = os.path.abspath(os.getcwd())
    for base in [here] + [os.path.dirname(here)]:
        cand = os.path.join(base, ".codex", "skills", "docx")
        if os.path.isfile(os.path.join(cand, "scripts", "document.py")):
            return cand
    for cand in glob.glob("/mnt/skills/*/docx"):
        if os.path.isfile(os.path.join(cand, "scripts", "document.py")):
            return cand
    raise SystemExit("document.py not found")

skill_root = find_skill_root()
sys.path.insert(0, skill_root)
from scripts.document import Document

doc = Document('unpacked')
xml = doc["word/document.xml"]
root = xml.dom.documentElement

ns = "http://schemas.openxmlformats.org/wordprocessingml/2006/main"
def q(t):
    return "{%s}%s" % (ns, t)

paragraphs = root.getElementsByTagName(q("p"))
print("total paragraphs:", len(paragraphs))
for i, p in enumerate(paragraphs):
    pPr = p.getElementsByTagName(q("pPr"))
    style = ""
    if pPr:
        pStyle = pPr[0].getElementsByTagName(q("pStyle"))
        if pStyle:
            style = pStyle[0].getAttribute(q("val"))
    if not style:
        continue
    # gather text
    texts = []
    for t in p.getElementsByTagName(q("t")):
        texts.append(t.firstChild.nodeValue if t.firstChild else "")
    for dt in p.getElementsByTagName(q("delText")):
        texts.append("[DEL:" + (dt.firstChild.nodeValue if dt.firstChild else "") + "]")
    txt = "".join(texts)
    print("IDX %d | style=%r | text=%r" % (i, style, txt[:120]))

